/** The three table snapshots, passed as a parameter so a Monte Carlo path stays deterministic against a pinned calibration. */
export interface RmdLifeExpectancyTables {
  readonly uniformLifetime: CalibrationSnapshot<RmdTable>;
  readonly singleLife: CalibrationSnapshot<SingleLifeTable>;
  readonly jointLastSurvivor: CalibrationSnapshot<JointLifeTable>;
}

export const RMD_LIFE_EXPECTANCY_TABLES: RmdLifeExpectancyTables = {
  uniformLifetime: RMD_UNIFORM_LIFETIME_TABLE_III,
  singleLife: RMD_SINGLE_LIFE_TABLE_I,
  jointLastSurvivor: RMD_JOINT_LIFE_TABLE_II,
};

/**
 * A request for one table's divisor. Single Life carries the inherited stretch mode: `recalculate` (surviving
 * spouse) looks up the current attained age each year; `anchoredDecrement` (non-spouse) fixes the divisor at
 * `baseAge` in the year after the owner's death, then subtracts 1.0 per elapsed year (`elapsedYears`, 0 in the base year).
 */
export type RmdTableRequest =
  | { readonly table: 'uniformLifetime'; readonly ownerAge: number }
  | { readonly table: 'singleLife'; readonly mode: 'recalculate'; readonly age: number }
  | {
      readonly table: 'singleLife';
      readonly mode: 'anchoredDecrement';
      readonly baseAge: number;
      readonly elapsedYears: number;
    }
  | { readonly table: 'jointLastSurvivor'; readonly ownerAge: number; readonly beneficiaryAge: number };

/** The resolved table and divisor, or a withhold when the required entry is unavailable. */
export type RmdTableSelection =
  | { readonly kind: 'divisor'; readonly table: RmdTableRequest['table']; readonly divisor: number }
  | { readonly kind: 'withheld'; readonly table: RmdTableRequest['table']; readonly reason: string };

function isUsableDivisor(value: unknown): value is number {
  return typeof value === 'number' && Number.isFinite(value) && value > 0;
}

function isNonNegativeSafeInteger(value: number): boolean {
  return Number.isSafeInteger(value) && value >= 0;
}

function divisorOrWithheld(
  table: RmdTableRequest['table'],
  divisor: number | undefined,
  reasonWhenMissing: string,
): RmdTableSelection {
  return isUsableDivisor(divisor)
    ? { kind: 'divisor', table, divisor }
    : { kind: 'withheld', table, reason: reasonWhenMissing };
}

/**
 * Divisor for one table request against a pinned bundle at `taxYear` (clamp-to-latest). A malformed age or
 * `taxYear`, or a missing entry, returns `withheld` rather than a guessed divisor.
 */
export function selectRmdTableDivisor(
  request: RmdTableRequest,
  tables: RmdLifeExpectancyTables,
  taxYear: number,
): RmdTableSelection {
  if (!isNonNegativeSafeInteger(taxYear)) {
    return {
      kind: 'withheld',
      table: request.table,
      reason: `taxYear must be a finite non-negative integer; got ${taxYear}`,
    };
  }

  if (request.table === 'uniformLifetime') {
    if (!isNonNegativeSafeInteger(request.ownerAge)) {
      return {
        kind: 'withheld',
        table: 'uniformLifetime',
        reason: `ownerAge must be a finite non-negative integer; got ${request.ownerAge}`,
      };
    }
    const table = resolveSnapshotValueForYear(tables.uniformLifetime, taxYear);
    return divisorOrWithheld(
      'uniformLifetime',
      table?.uniformLifetime[clampAge(request.ownerAge, 73)],
      `Uniform Lifetime (Table III) divisor unavailable for age ${request.ownerAge}`,
    );
  }

  if (request.table === 'singleLife') {
    const table = resolveSnapshotValueForYear(tables.singleLife, taxYear);
    if (request.mode === 'recalculate') {
      if (!isNonNegativeSafeInteger(request.age)) {
        return {
          kind: 'withheld',
          table: 'singleLife',
          reason: `age must be a finite non-negative integer; got ${request.age}`,
        };
      }
      return divisorOrWithheld(
        'singleLife',
        table?.singleLife[clampAge(request.age, 0)],
        `Single Life (Table I) divisor unavailable for age ${request.age}`,
      );
    }
    if (!isNonNegativeSafeInteger(request.baseAge) || !isNonNegativeSafeInteger(request.elapsedYears)) {
      return {
        kind: 'withheld',
        table: 'singleLife',
        reason:
          `Single Life (Table I) anchored request needs non-negative integer baseAge / ` +
          `elapsedYears; got baseAge ${request.baseAge}, elapsedYears ${request.elapsedYears}`,
      };
    }
    const baseDivisor = table?.singleLife[clampAge(request.baseAge, 0)];
    if (!isUsableDivisor(baseDivisor)) {
      return {
        kind: 'withheld',
        table: 'singleLife',
        reason: `Single Life (Table I) base-year divisor unavailable for age ${request.baseAge}`,
      };
    }
    // A non-positive result means the stretch schedule is exhausted (the account must be emptied).
    return divisorOrWithheld(
      'singleLife',
      baseDivisor - request.elapsedYears,
      `Single Life (Table I) anchored divisor exhausted for base age ${request.baseAge} ` +
        `after ${request.elapsedYears} elapsed year(s)`,
    );
  }

  if (!isNonNegativeSafeInteger(request.ownerAge) || !isNonNegativeSafeInteger(request.beneficiaryAge)) {
    return {
      kind: 'withheld',
      table: 'jointLastSurvivor',
      reason:
        `Joint Life (Table II) request needs non-negative integer ages; got ` +
        `owner age ${request.ownerAge} / beneficiary age ${request.beneficiaryAge}`,
    };
  }
  const table = resolveSnapshotValueForYear(tables.jointLastSurvivor, taxYear);
  const divisor = table?.jointLastSurvivor[clampAge(request.ownerAge, 0)]?.[clampAge(request.beneficiaryAge, 0)];
  return divisorOrWithheld(
    'jointLastSurvivor',
    divisor,
    `Joint Life and Last Survivor (Table II) divisor unavailable for ` +
      `owner age ${request.ownerAge} / beneficiary age ${request.beneficiaryAge}`,
  );
}
